def compute(vars):
    restricted_cash_and_securities = vars["v1"]
    allowance_for_doubtful_accounts = vars["v2"]

    if allowance_for_doubtful_accounts == 0:
        return None

    value = restricted_cash_and_securities / allowance_for_doubtful_accounts

    return {
        "value": value,
        "trace": {
            "restricted_cash_and_securities": restricted_cash_and_securities,
            "allowance_for_doubtful_accounts": allowance_for_doubtful_accounts,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
